fn main(){let args=std::env::args().collect::<Vec<_>>();let p=std::path::Path::new(&args[1]);let audio=premidi_decoder::decode(std::fs::read(p).unwrap(),p.extension().unwrap().to_str().unwrap()).unwrap();let mut data=Vec::with_capacity(audio.samples.len()*4);for v in &audio.samples{data.extend(v.to_le_bytes());}std::fs::write(&args[2],data).unwrap();println!("{} {} {} {}",audio.rate,audio.channels,audio.samples.len(),audio.peak);}
